   904→// GitCommitWithShadowHooks stages and commits files, simulating the prepare-commit-msg and post-commit hooks.
   905→// This is used for testing manual-commit strategy which needs:
   906→// - prepare-commit-msg hook: adds the Entire-Checkpoint trailer
   907→// - post-commit hook: condenses session data if trailer is present
   908→func (env *TestEnv) GitCommitWithShadowHooks(message string, files ...string) {
   909→	env.T.Helper()
   910→
   911→	// Stage files using go-git
   912→	for _, file := range files {
   913→		env.GitAdd(file)
   914→	}
   915→
   916→	// Create a temp file for the commit message (prepare-commit-msg hook modifies this)
   917→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
   918→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
   919→		env.T.Fatalf("failed to write commit message file: %v", err)
   920→	}
   921→
   922→	// Run prepare-commit-msg hook using the shared binary.
   923→	// Pass source="message" to match real `git commit -m` behavior.
   924→	// Set ENTIRE_TEST_HAS_TTY=1 to simulate a human at the terminal (default for tests).
   925→	// Without this, the no-TTY fast path would fire in CI and mask content detection bugs.
   926→	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile, "message")
   927→	prepCmd.Dir = env.RepoDir
   928→	prepCmd.Env = append(os.Environ(), "ENTIRE_TEST_HAS_TTY=1")
   929→	if output, err := prepCmd.CombinedOutput(); err != nil {
   930→		env.T.Logf("prepare-commit-msg output: %s", output)
   931→		// Don't fail - hook may silently succeed
   932→	}
   933→
   934→	// Read the modified message
   935→	modifiedMsg, err := os.ReadFile(msgFile)
   936→	if err != nil {
   937→		env.T.Fatalf("failed to read modified commit message: %v", err)
   938→	}
   939→
   940→	// Create the commit using go-git with the modified message
   941→	repo, err := git.PlainOpen(env.RepoDir)
   942→	if err != nil {
   943→		env.T.Fatalf("failed to open git repo: %v", err)
   944→	}
   945→
   946→	worktree, err := repo.Worktree()
   947→	if err != nil {
   948→		env.T.Fatalf("failed to get worktree: %v", err)
   949→	}
   950→
   951→	_, err = worktree.Commit(string(modifiedMsg), &git.CommitOptions{
   952→		Author: &object.Signature{
   953→			Name:  "Test User",
   954→			Email: "test@example.com",
   955→			When:  time.Now(),
   956→		},
   957→	})
   958→	if err != nil {
   959→		env.T.Fatalf("failed to commit: %v", err)
   960→	}
   961→
   962→	// Run post-commit hook using the shared binary
   963→	// This triggers condensation if the commit has an Entire-Checkpoint trailer
   964→	postCmd := exec.Command(getTestBinary(), "hooks", "git", "post-commit")
   965→	postCmd.Dir = env.RepoDir
   966→	if output, err := postCmd.CombinedOutput(); err != nil {
   967→		env.T.Logf("post-commit output: %s", output)
   968→		// Don't fail - hook may silently succeed
   969→	}
   970→}
