  1034→// filterEnv returns a copy of env with the specified key removed.
  1035→func filterEnv(env []string, key string) []string {
  1036→	prefix := key + "="
  1037→	result := make([]string, 0, len(env))
  1038→	for _, e := range env {
  1039→		if !strings.HasPrefix(e, prefix) {
  1040→			result = append(result, e)
  1041→		}
  1042→	}
  1043→	return result
  1044→}
