  1046→// GitCommitAmendWithShadowHooks amends the last commit with shadow hooks.
  1047→// This simulates `git commit --amend` with the prepare-commit-msg and post-commit hooks.
  1048→// The prepare-commit-msg hook is called with "commit" source to indicate an amend.
  1049→func (env *TestEnv) GitCommitAmendWithShadowHooks(message string, files ...string) {
  1050→	env.T.Helper()
  1051→
  1052→	// Stage any additional files
  1053→	for _, file := range files {
  1054→		env.GitAdd(file)
  1055→	}
  1056→
  1057→	// Write commit message to temp file
  1058→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
  1059→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
  1060→		env.T.Fatalf("failed to write commit message file: %v", err)
  1061→	}
  1062→
