  1108→// GitCommitWithTrailerRemoved stages and commits files, simulating what happens when
  1109→// a user removes the Entire-Checkpoint trailer during commit message editing.
  1110→// This tests the opt-out behavior where removing the trailer skips condensation.
  1111→func (env *TestEnv) GitCommitWithTrailerRemoved(message string, files ...string) {
  1112→	env.T.Helper()
  1113→
  1114→	// Stage files using go-git
  1115→	for _, file := range files {
  1116→		env.GitAdd(file)
