  1120→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
  1121→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
  1122→		env.T.Fatalf("failed to write commit message file: %v", err)
  1123→	}
  1124→
  1125→	// Run prepare-commit-msg hook using the shared binary
  1126→	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile)
  1127→	prepCmd.Dir = env.RepoDir
  1128→	if output, err := prepCmd.CombinedOutput(); err != nil {
  1129→		env.T.Logf("prepare-commit-msg output: %s", output)
  1130→	}
  1131→
  1132→	// Read the modified message (with trailer added by hook)
  1133→	modifiedMsg, err := os.ReadFile(msgFile)
  1134→	if err != nil {
  1135→		env.T.Fatalf("failed to read modified commit message: %v", err)
