  1139→	lines := strings.Split(string(modifiedMsg), "\n")
  1140→	var cleanedLines []string
  1141→	for _, line := range lines {
  1142→		// Skip the trailer and the comments about it
  1143→		if strings.HasPrefix(line, "Entire-Checkpoint:") {
  1144→			continue
  1145→		}
  1146→		if strings.Contains(line, "Remove the Entire-Checkpoint trailer") {
  1147→			continue
  1148→		}
  1149→		if strings.Contains(line, "trailer will be added to your next commit") {
  1150→			continue
  1151→		}
  1152→		cleanedLines = append(cleanedLines, line)
