  1167→	_, err = worktree.Commit(cleanedMsg, &git.CommitOptions{
  1168→		Author: &object.Signature{
  1169→			Name:  "Test User",
  1170→			Email: "test@example.com",
  1171→			When:  time.Now(),
  1172→		},
  1173→	})
  1174→	if err != nil {
  1175→		env.T.Fatalf("failed to commit: %v", err)
  1176→	}
  1177→
