  1366→func findModuleRoot() string {
  1367→	// Start from this source file's location and walk up to find go.mod
  1368→	_, thisFile, _, ok := runtime.Caller(0)
  1369→	if !ok {
  1370→		panic("failed to get current file path via runtime.Caller")
  1371→	}
  1372→	dir := filepath.Dir(thisFile)
  1373→
  1374→	for {
  1375→		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
  1376→			return dir
  1377→		}
  1378→		parent := filepath.Dir(dir)
  1379→		if parent == dir {
  1380→			panic("could not find go.mod starting from " + thisFile)
  1381→		}
  1382→		dir = parent
  1383→	}
  1384→}
